/**
 * Fake Electron main process for the print engine tests: BrowserWindow records what the
 * engine does (loadURL, print options, timing) and answers like Chromium would.
 * `state` is shared with the test through this module instance (same NODE_PATH resolution).
 */
const { EventEmitter } = require('events');

const state = {
    windows: [],
    prints: [],              // { deviceName, options, startedAt, finishedAt }
    activePrints: 0,
    maxActivePrints: 0,
    failDevices: new Set(),  // device names whose print callback answers (false, reason)
    printDelayMs: 40,
    measure: { heightPx: 1000, widthPx: 302, pageSize: null },
};

class WebContents extends EventEmitter {
    constructor(win) {
        super();
        this.win = win;
        this.calls = [];
        this.debugger = {
            attached: false,
            isAttached: () => this.debugger.attached,
            attach: () => { this.debugger.attached = true; },
            sendCommand: async (method, params) => { this.calls.push(['cdp', method, params]); },
        };
    }
    setWindowOpenHandler() {}
    setAudioMuted() {}
    executeJavaScript(script) {
        this.calls.push(['executeJavaScript', script.slice(0, 40)]);
        if (/scrollHeight/.test(script)) return Promise.resolve({ ...state.measure });
        return Promise.resolve(true);
    }
    getPrintersAsync() {
        return Promise.resolve([
            { name: 'Kitchen POS-80', displayName: 'Kitchen POS-80', isDefault: true, status: 0 },
            { name: 'Bar XP-58', displayName: 'Bar XP-58', isDefault: false, status: 0 },
        ]);
    }
    print(options, callback) {
        const rec = { deviceName: options.deviceName, options, startedAt: Date.now(), finishedAt: null };
        state.prints.push(rec);
        state.activePrints++;
        state.maxActivePrints = Math.max(state.maxActivePrints, state.activePrints);
        setTimeout(() => {
            state.activePrints--;
            rec.finishedAt = Date.now();
            if (state.failDevices.has(options.deviceName)) callback(false, 'Invalid printer settings');
            else callback(true, '');
        }, state.printDelayMs);
    }
}

class BrowserWindow extends EventEmitter {
    constructor(options) {
        super();
        this.options = options;
        this.destroyed = false;
        this.loads = [];
        this.webContents = new WebContents(this);
        state.windows.push(this);
    }
    loadURL(url) {
        this.loads.push({ url, at: Date.now() });
        return new Promise((resolve) => {
            setImmediate(() => {
                this.webContents.emit('dom-ready');
                this.webContents.emit('did-finish-load');
                resolve();
            });
        });
    }
    loadFile(file) { return this.loadURL('file://' + file); }
    setContentSize(w, h) { this.size = [w, h]; }
    isDestroyed() { return this.destroyed; }
    destroy() { this.destroyed = true; this.emit('closed'); }
    close() { this.destroy(); }
}

const app = {
    isReady: () => true,
    whenReady: () => Promise.resolve(),
};

module.exports = { app, BrowserWindow, __state: state };
